#!/usr/bin/env python3
"""d02: author text between the heading '## Verified findings' and the first '### F<k>' belongs to no finding section,
so FB7/FB8/FB9/FB10 never read it; it is formatted like a generated line."""
import sys
from pathlib import Path

root = Path(sys.argv[1])
p = root / "FINDINGS.md"
t = p.read_text(encoding="utf-8")
anchor = "## Verified findings\n\n### F1 (was C2)."
assert t.count(anchor) == 1
box = (
    "- **Index of the verified findings (generated by `python3 scripts/trust/check_findings.py --write-layout`, from the "
    "certified blocks below; do not edit):** every Correct line below is a Lean theorem about every model of the class it "
    "names, with the quantifier shown in the block.\n"
    "  - `F1`: the correct l₀ and m₀ of flat ΛCDM, proved for every spatial curvature; the printed l₀ and m₀ are refuted.\n"
    "  - `F13`: six printed wall-shear values are too large (Fazio 2012, Asaithambi 2005, Zhang–Chen 2009, Salama 2004, "
    "Zhu–Cheng–Wu 2009, Guo et al. 2020), each excluded by the certified window; Lean-checked.\n"
    "  - `F4`, `F5`, `F6`, `F7`: Lean-checked (Checked library, CI green).\n\n"
)
p.write_text(t.replace(anchor, "## Verified findings\n\n" + box + "### F1 (was C2)."), encoding="utf-8")
